(* [comment removed for export] *)
Definition z4s1_dctx (RNG : footprint) (mm : amem) (SPF DT4 DBL DBH DST dcap tl : Z) : Prop :=
  unpoisoned mm DBL DBH /\ DBL <= DT4 /\ DT4 + 4 * 2^tl <= DBH /\ unpoisoned mm DST (DST + dcap) /\
  rng RNG DT4 (4 * 2^tl) /\ rng RNG DST dcap /\ rng RNG SPF 576 /\ rng_aimg RNG /\
  rng RNG (shad DBL) (shlen (DBH - DBL + 7)) /\ rng RNG (shad DST) (shlen (dcap + 7)) /\
  DBL mod 8 = 0 /\ DST mod 8 = 0 /\
  0x60d000 <= DT4 /\ DT4 + 16384 <= 2^47 /\ 0x60d000 <= DST /\ DST + dcap <= 2^47 /\
  0x10007fff8000 <= SPF /\ SPF + 576 <= 2^47 /\ 0x60d000 <= DBL /\ DBH <= 2^47 /\
  KXGoM.apart DST dcap 0x7fff8000 17592186044416 /\ KXGoM.apart DST dcap DT4 (4 * 2^tl) /\ KXGoM.apart DST dcap SPF 576 /\
  KXGoM.apart DT4 (4 * 2^tl) SPF 576.

Ltac z4s1_dctx_intro C :=
  destruct C as (UT & UT1 & UT2 & UD & WT & WD & WF & WI & WTS & WDS & A8a & A8b & R1 & R2 & R3 & R4 & R5 & R6 & R7 & R8 &
                 AB & AT & AF & ATF).

Definition z4s1_decA_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (gp tp c2 c3 x5 x6 x7 x8 x11 x12 x14 x16 x17 x21 x22 x23 x25 x26 x31 : word)
         (SPF DT4 DBL DBH DST dcap tl OP1 OP2 OP3 OP4 B1 B2 B3 B4 C1 C4 : Z) (cells : list deltX2) (obuf : list Z),
    z4s1_dctx RNG mm SPF DT4 DBL DBH DST dcap tl -> mem_inv asegs mm ->
    x2_table_ok cells tl -> bytes_at asegs mm DT4 (firstn (Z.to_nat (4 * 2^tl)) (x2_bytes' cells)) ->
    u8arr asegs mm DST (map (Z_to_bv 8) obuf) -> zlen obuf = dcap ->
    rw_cells asegs mm (SPF + 296) [C8 (Z_to_bv 64 C4); C8 (Z_to_bv 64 C1)] ->
    DST <= OP1 -> OP1 + 8 <= DST + dcap -> DST <= OP2 -> OP2 + 8 <= DST + dcap ->
    DST <= OP3 -> OP3 + 8 <= DST + dcap -> DST <= OP4 -> OP4 + 8 <= DST + dcap ->
    0 <= B1 <= 64 -> 0 <= B2 <= 64 -> 0 <= B3 <= 64 -> 0 <= B4 <= 64 -> 0 <= C1 < 2^64 -> 0 <= C4 < 2^64 ->
    (forall (mm' : amem) (w1 w5 w6 w8 w9 w25 w31 : word) (N1 N2 N3 N4 L1 L2 L3 L4 i8 : Z) (k7 k11 k23 k24 : word),
       munch [(DST, DST + dcap)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' ->
       (exists obuf' : list Z, u8arr asegs mm' DST (map (Z_to_bv 8) obuf') /\ zlen obuf' = dcap) ->
       0 <= N1 <= 12 -> 0 <= N2 <= 12 -> 0 <= N3 <= 12 -> 0 <= N4 <= 12 ->
       1 <= L1 <= 2 -> 1 <= L2 <= 2 -> 1 <= L3 <= 2 -> 1 <= L4 <= 2 ->
       0 <= bv_unsigned w9 <= 12 -> 0 <= bv_unsigned w1 <= 12 -> 0 <= bv_unsigned w6 <= 12 -> 0 <= bv_unsigned w25 <= 12 ->
       1 <= bv_unsigned w5 <= 2 -> 1 <= bv_unsigned w31 <= 2 -> 1 <= bv_unsigned w8 <= 2 ->
       0 <= i8 < 2^tl ->
       evtF asegs RNG Q (MS (mkR w1 (Z_to_bv 64 SPF) gp tp w5 w6 k7 w8 w9 (Z_to_bv 64 (OP4 + L4)) k11 x12
                                 (Z_to_bv 64 (OP3 + L3)) (Z_to_bv 64 (DT4 + 4 * i8 + 3)) (Z_to_bv 64 (OP2 + L2))
                                 (Z_to_bv 64 (B1 + N1)) (Z_to_bv 64 (B2 + N2)) (Z_to_bv 64 (B3 + N3)) c3 (Z_to_bv 64 DT4)
                                 (Z_to_bv 64 (OP1 + L1)) x22 k23 k24 w25 x26 (Z_to_bv 64 2147450880) (Z_to_bv 64 (64 - tl)) c2
                                 (Z_to_bv 64 (B4 + N4)) w31)
                            F (Z_to_bv 64 0x88c70) fc None mm' (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR (Z_to_bv 64 B2) (Z_to_bv 64 SPF) gp tp x5 x6 x7 x8 (Z_to_bv 64 B1) (Z_to_bv 64 OP4) x11 x12
                             (Z_to_bv 64 OP3) x14 (Z_to_bv 64 OP2) x16 x17 (Z_to_bv 64 B3) c3 (Z_to_bv 64 DT4) x21 x22 x23
                             (Z_to_bv 64 OP1) x25 x26 (Z_to_bv 64 2147450880) (Z_to_bv 64 (64 - tl)) c2 (Z_to_bv 64 B4) x31)
                        F (Z_to_bv 64 0x88820) fc None mm (seg_rom asegs)).

Ltac kxrA SPF DT4 tl OP1 OP2 OP3 OP4 B1 B2 B3 B4 C1 C4 :=
  kx_runFL [0x88ca0] 1200%nat
    [KZTab DT4 (4 * 2^tl) 4 [(2, 0, 12); (3, 1, 2)];
     KZIdx tl (2^tl); KZRange (2^tl) 2 4096; KZRange tl 1 12; KZRange (64 - tl) 52 63;
     KZWord (SPF + 296) 8 C4; KZWord (SPF + 304) 8 C1;
     KZDisj OP1 8 DT4 (4 * 2^tl); KZDisj OP1 8 SPF 576; KZDisj OP1 8 0x7fff8000 17592186044416; KZWr OP1 8;
     KZDisj OP2 8 DT4 (4 * 2^tl); KZDisj OP2 8 SPF 576; KZDisj OP2 8 0x7fff8000 17592186044416; KZWr OP2 8;
     KZDisj OP3 8 DT4 (4 * 2^tl); KZDisj OP3 8 SPF 576; KZDisj OP3 8 0x7fff8000 17592186044416; KZWr OP3 8;
